WITH valid_subscriptions AS (SELECT * FROM subscriptions WHERE YEAR(start_date) >= 2023 AND status IN ('CANCELLED', 'ACTIVE', 'EXPIRED')), Summary AS (SELECT MONTH(start_date) start_month, AVG(monthly_fee) avg_monthly_fee, COUNT(DISTINCT monthly_fee) unique_customers FROM valid_subscriptions GROUP BY MONTH(start_date)) SELECT start_month, unique_customers FROM Summary WHERE unique_customers > 5 ORDER BY start_month;
